import os
import posixpath
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
if not os.path.exists(path):
    raise SystemExit("ERROR: %s not found" % path)

REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def get_ns(el):
    m = re.match(r"\{([^}]+)\}", el.tag)
    return m.group(1) if m else ""


def q(ns, tag):
    return "{%s}%s" % (ns, tag)


def col_letter(ref):
    m = re.match(r"([A-Z]+)\d+", ref or "")
    return m.group(1) if m else None


def col_index(letter):
    n = 0
    for ch in letter:
        n = n * 26 + ord(ch) - 64
    return n


def num_to_letter(idx):
    s = ""
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s


def find_col(headers, keywords, exclude=()):
    return [(i, h) for i, h in headers.items()
            if all(k in h for k in keywords) and not any(e in h for e in exclude)]


zin = zipfile.ZipFile(path)
entries = {i.filename: i for i in zin.infolist()}
blobs = {name: zin.read(name) for name in entries}
zin.close()

wb_root = ET.fromstring(blobs["xl/workbook.xml"])
ns = get_ns(wb_root)
ET.register_namespace("", ns)
ET.register_namespace("r", REL)

rels_root = ET.fromstring(blobs["xl/_rels/workbook.xml.rels"])
rid2target = {r.get("Id"): r.get("Target") for r in rels_root}

shared = []
if "xl/sharedStrings.xml" in blobs:
    ss_root = ET.fromstring(blobs["xl/sharedStrings.xml"])
    sns = get_ns(ss_root)
    for si in ss_root.findall(q(sns, "si")):
        shared.append("".join(t.text or "" for t in si.iter(q(sns, "t"))))


def cell_value(c, sh_ns):
    t = c.get("t")
    if t == "inlineStr":
        is_ = c.find(q(sh_ns, "is"))
        return "".join(x.text or "" for x in is_.iter(q(sh_ns, "t"))) if is_ is not None else ""
    v = c.find(q(sh_ns, "v"))
    if v is None or v.text is None:
        return ""
    if t == "s":
        try:
            return shared[int(v.text)]
        except (ValueError, IndexError):
            return v.text
    return v.text


def sheet_headers(sh_root, sh_ns):
    sheetData = sh_root.find(q(sh_ns, "sheetData"))
    rows = sheetData.findall(q(sh_ns, "row")) if sheetData is not None else []
    hr = next((r for r in rows if r.get("r") == "1"), rows[0] if rows else None)
    if hr is None:
        return {}, []
    hdrs = {}
    for c in hr.findall(q(sh_ns, "c")):
        L = col_letter(c.get("r"))
        if L:
            hdrs.setdefault(col_index(L), cell_value(c, sh_ns).strip().lower())
    return hdrs, rows


# pick the sheet containing profit and revenue/sales headers
sheet_target = None
rows_by_r = None
root = None
for s in wb_root.find(q(ns, "sheets")):
    tgt = rid2target.get(s.get(q(REL, "id")))
    if not tgt:
        continue
    cand = tgt.lstrip("/") if tgt.startswith("/") else posixpath.normpath(posixpath.join("xl", tgt))
    if cand not in blobs:
        continue
    sh_root = ET.fromstring(blobs[cand])
    sh_ns = get_ns(sh_root)
    hdrs, rows = sheet_headers(sh_root, sh_ns)
    if find_col(hdrs, ["profit"], ["margin"]) and (find_col(hdrs, ["revenue"]) or find_col(hdrs, ["sales"], ["qty", "quantity", "units", "volume", "count", "margin"])):
        sheet_target = cand
        root, ns = sh_root, sh_ns
        rows_by_r = {int(r.get("r") or 0): r for r in rows}
        headers = hdrs
        break
if not sheet_target:
    raise SystemExit("ERROR: no sheet with profit and revenue/sales columns found")

print("Sheet:", sheet_target)
print("Headers:", {num_to_letter(i): h for i, h in headers.items()})

profit_cands = find_col(headers, ["profit"], ["margin"])
rev_cands = find_col(headers, ["revenue"]) + find_col(headers, ["sales"], ["qty", "quantity", "units", "volume", "count", "margin"])


def rank(h):
    return (3 if "revenue" in h else 0) + (2 if "amount" in h else 0) + (1 if "value" in h else 0) + (1 if "net" in h else 0)


prof_idx = profit_cands[0][0]
rev_idx = max(rev_cands, key=lambda c: rank(c[1]))[0]

max_col = 0
max_row = max(rows_by_r) if rows_by_r else 0
for r, row_el in rows_by_r.items():
    for c in row_el.findall(q(ns, "c")):
        L = col_letter(c.get("r"))
        if L:
            max_col = max(max_col, col_index(L))

new_idx = max_col + 1
newL = num_to_letter(new_idx)
profL, revL = num_to_letter(prof_idx), num_to_letter(rev_idx)

header_row = rows_by_r.get(1) or next(iter(rows_by_r.values()))
hc = ET.SubElement(header_row, q(ns, "c"))
hc.set("r", "%s1" % newL)
hc.set("t", "inlineStr")
is_ = ET.SubElement(hc, q(ns, "is"))
ET.SubElement(is_, q(ns, "t")).text = "Profit Margin (%)"

# number format 0.0% via styles.xml
fmt_idx = None
st_bytes = None
if "xl/styles.xml" in blobs:
    try:
        st_root = ET.fromstring(blobs["xl/styles.xml"])
        sns = get_ns(st_root)
        numFmts = st_root.find(q(sns, "numFmts"))
        fmt_id = 164
        if numFmts is None:
            numFmts = ET.Element(q(sns, "numFmts"))
            cellXfs = st_root.find(q(sns, "cellXfs"))
            if cellXfs is not None:
                st_root.insert(list(st_root).index(cellXfs), numFmts)
            else:
                st_root.append(numFmts)
            numFmts.set("count", "0")
        for nf in numFmts.findall(q(sns, "numFmt")):
            try:
                fmt_id = max(fmt_id, int(nf.get("numFmtId")) + 1)
            except (TypeError, ValueError):
                pass
        nf = ET.SubElement(numFmts, q(sns, "numFmt"))
        nf.set("numFmtId", str(fmt_id))
        nf.set("formatCode", "0.0%")
        numFmts.set("count", str(len(numFmts.findall(q(sns, "numFmt")))))
        cellXfs = st_root.find(q(sns, "cellXfs"))
        if cellXfs is not None:
            xf = ET.SubElement(cellXfs, q(sns, "xf"))
            xf.set("numFmtId", str(fmt_id))
            xf.set("applyNumberFormat", "1")
            cellXfs.set("count", str(len(cellXfs.findall(q(sns, "xf")))))
            fmt_idx = len(cellXfs.findall(q(sns, "xf"))) - 1
        st_bytes = ET.tostring(st_root, encoding="UTF-8", xml_declaration=True)
    except Exception as e:  # noqa: BLE001
        print("WARN: styles update skipped:", e)

count = 0
for r in range(2, max_row + 1):
    row_el = rows_by_r.get(r)
    if row_el is None:
        continue
    refs = {col_letter(c.get("r")) for c in row_el.findall(q(ns, "c")) if c.get("r")}
    if profL not in refs and revL not in refs:
        continue
    c = ET.SubElement(row_el, q(ns, "c"))
    c.set("r", "%s%d" % (newL, r))
    if fmt_idx is not None:
        c.set("s", str(fmt_idx))
    f = ET.SubElement(c, q(ns, "f"))
    f.text = 'IF(AND(ISNUMBER(%s%d),ISNUMBER(%s%d),%s%d<>0),%s%d/%s%d,"")' % (revL, r, profL, r, revL, r, profL, r, revL, r)
    count += 1

dim = root.find(q(ns, "dimension"))
if dim is not None:
    dim.set("ref", "A1:%s%d" % (newL, max_row))

sheet_bytes = ET.tostring(root, encoding="UTF-8", xml_declaration=True)

zout = zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED)
for name, info in entries.items():
    if name == sheet_target:
        zout.writestr(info, sheet_bytes)
    elif name == "xl/styles.xml" and st_bytes is not None:
        zout.writestr(info, st_bytes)
    else:
        zout.writestr(info, blobs[name])
zout.close()

print("Added 'Profit Margin (%)' at column %s (profit=%s, revenue=%s, data rows=%d)" % (newL, profL, revL, count))
print('Sample formula (row 2): =IF(AND(ISNUMBER(%s2),ISNUMBER(%s2),%s2<>0),%s2/%s2,"")' % (revL, profL, revL, profL, revL))

import re
import sys
import zipfile
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
