        continue
    for c in rows[rn].findall(q(ns, "c")):
        ref = c.get("r") or ""
        if ref.startswith(colL):
            f = c.find(q(ns, "f"))
            v = c.find(q(ns, "v"))
            if f is not None:
                formulas += 1
                if len(samples) < 3:
                    samples.append((ref, f.text))
            if v is not None:
                cached.append((ref, v.text))
print("Formula cells in column %s:" % colL, formulas)
for s in samples:
    print("  sample:", s)
print("Cached values:", cached[:5])

if "xl/styles.xml" in blobs:
    st = ET.fromstring(blobs["xl/styles.xml"])
    sns = get_ns(st)
    fmts = [nf.get("formatCode") for nf in st.find(q(sns, "numFmts")).findall(q(sns, "numFmt"))]
    print("numFmts contain '0.0%':", "0.0%" in fmts)
    cellXfs = st.find(q(sns, "cellXfs"))
    print("cellXfs count:", cellXfs.get("count"))

dim = root.find(q(ns, "dimension"))
print("dimension:", dim.get("ref") if dim is not None else None)

import json
import os
import platform
import re
import shutil
import subprocess
import sys
import zipfile
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
if not os.path.exists(path):
    raise SystemExit("ERROR: %s not found" % path)

soffice = next((shutil.which(n) for n in ("soffice", "libreoffice", "loffice") if shutil.which(n)), None)
if not soffice:
    raise SystemExit("ERROR: LibreOffice (soffice) not found; cannot recalculate formulas")

# --- configure LibreOffice Basic macro (same as the skill's recalc helper) ---
if platform.system() == "Darwin":
    macro_dir = os.path.expanduser("~/Library/Application Support/LibreOffice/4/user/basic/Standard")
else:
    macro_dir = os.path.expanduser("~/.config/libreoffice/4/user/basic/Standard")
macro_file = os.path.join(macro_dir, "Module1.xba")

if not (os.path.exists(macro_file) and "RecalculateAndSave" in open(macro_file).read()):
    if not os.path.exists(macro_dir):
        subprocess.run([soffice, "--headless", "--terminate_after_init"], capture_output=True, timeout=15)
        os.makedirs(macro_dir, exist_ok=True)
    macro_content = '<?xml version="1.0" encoding="UTF-8"?>\n' \
        '<!DOCTYPE script:module PUBLIC "-//OpenOffice.org//DTD OfficeDocument 1.0//EN" "module.dtd">\n' \
        '<script:module xmlns:script="http://openoffice.org/2000/script" script:name="Module1" script:language="StarBasic">\n' \
        '    Sub RecalculateAndSave()\n' \
        '      ThisComponent.calculateAll()\n' \
        '      ThisComponent.store()\n' \
        '      ThisComponent.close(True)\n' \
        '    End Sub\n' \
        '</script:module>\n'
    with open(macro_file, "w") as f:
        f.write(macro_content)

# --- recalculate ---
cmd = [soffice, "--headless", "--norestore",
       "vnd.sun.star.script:Standard.Module1.RecalculateAndSave?language=Basic&location=application",
       os.path.abspath(path)]
try:
    res = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
except subprocess.TimeoutExpired:
    raise SystemExit("ERROR: LibreOffice recalculation timed out")
if res.returncode != 0:
    raise SystemExit("ERROR: soffice failed (%d): %s" % (res.returncode, (res.stderr or res.stdout or "")))

# --- scan all sheets for formula errors and count formulas (stdlib XML scan) ---
zin = zipfile.ZipFile(path)
blobs = {n: zin.read(n) for n in zin.namelist()}
zin.close()

REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def get_ns(el):
    m = re.match(r"\{([^}]+)\}", el.tag)
    return m.group(1) if m else ""


def q(ns, tag):
    return "{%s}%s" % (ns, tag)


wb_root = ET.fromstring(blobs["xl/workbook.xml"])
ns = get_ns(wb_root)
rels_root = ET.fromstring(blobs["xl/_rels/workbook.xml.rels"])
rid2target = {r.get("Id"): r.get("Target") for r in rels_root}
sheet_parts = []
for s in wb_root.find(q(ns, "sheets")):
    tgt = rid2target.get(s.get(q(REL, "id")))
    if not tgt:
        continue
    cand = tgt.lstrip("/") if tgt.startswith("/") else os.path.normpath(os.path.join("xl", tgt))
    if cand in blobs:
        sheet_parts.append((s.get("name"), cand))

shared = []
if "xl/sharedStrings.xml" in blobs:
    ss_root = ET.fromstring(blobs["xl/sharedStrings.xml"])
    sns = get_ns(ss_root)
    for si in ss_root.findall(q(sns, "si")):
        shared.append("".join(t.text or "" for t in si.iter(q(sns, "t"))))

ERRORS = ("#VALUE!", "#DIV/0!", "#REF!", "#NAME?", "#NULL!", "#NUM!", "#N/A")
total_errors = 0
total_formulas = 0
error_summary = {e: [] for e in ERRORS}
cached_margin = []

for sname, part in sheet_parts:
    root = ET.fromstring(blobs[part])
    sns = get_ns(root)
    sheetData = root.find(q(sns, "sheetData"))
    if sheetData is None:
        continue
    for row in sheetData.findall(q(sns, "row")):
        for c in row.findall(q(sns, "c")):
            ref = c.get("r") or ""
            f = c.find(q(sns, "f"))
            if f is not None:
                total_formulas += 1
            texts = []
            v = c.find(q(sns, "v"))
            if v is not None and v.text:
                texts.append(v.text)
            if c.get("t") == "s" and v is not None and v.text:
                try:
                    texts.append(shared[int(v.text)])
                except (ValueError, IndexError):
                    pass
            if c.get("t") == "inlineStr":
                is_ = c.find(q(sns, "is"))
                if is_ is not None:
                    texts.append("".join(x.text or "" for x in is_.iter(q(sns, "t"))))
            for text in texts:
                for err in ERRORS:
                    if err in text:
                        error_summary[err].append("%s!%s" % (sname, ref))
                        total_errors += 1
                        break
            if ref.startswith("H") and v is not None and v.text and len(cached_margin) < 5:
                cached_margin.append((ref, v.text))

result = {
    "status": "success" if total_errors == 0 else "errors_found",
    "total_errors": total_errors,
    "total_formulas": total_formulas,
    "error_summary": {k: {"count": len(v), "locations": v[:20]} for k, v in error_summary.items() if v},
    "cached_margin_samples": cached_margin,
}
print(json.dumps(result, indent=2))

import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
if not os.path.exists(path):
    raise SystemExit("ERROR: %s not found" % path)

REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def get_ns(el):
    m = re.match(r"\{([^}]+)\}", el.tag)
    return m.group(1) if m else ""


def q(ns, tag):
    return "{%s}%s" % (ns, tag)


def col_letter(ref):
    m = re.match(r"([A-Z]+)\d+", ref or "")
    return m.group(1) if m else None


zin = zipfile.ZipFile(path)
entries = {i.filename: i for i in zin.infolist()}
blobs = {n: zin.read(n) for n in entries}
zin.close()

wb_root = ET.fromstring(blobs["xl/workbook.xml"])
ns = get_ns(wb_root)
rels_root = ET.fromstring(blobs["xl/_rels/workbook.xml.rels"])
rid2target = {r.get("Id"): r.get("Target") for r in rels_root}

shared = []
if "xl/sharedStrings.xml" in blobs:
    ss_root = ET.fromstring(blobs["xl/sharedStrings.xml"])
    sns = get_ns(ss_root)
    for si in ss_root.findall(q(sns, "si")):
        shared.append("".join(t.text or "" for t in si.iter(q(sns, "t"))))


def raw_value(c, sns):
    t = c.get("t")
    v = c.find(q(sns, "v"))
    if v is None or v.text is None:
        return None
    if t == "s":
        try:
            return shared[int(v.text)]
        except (ValueError, IndexError):
            return v.text
    if t == "inlineStr":
        is_ = c.find(q(sns, "is"))
        return "".join(x.text or "" for x in is_.iter(q(sns, "t"))) if is_ is not None else ""
    return v.text


def to_num(x):
    if x is None:
        return None
    if isinstance(x, (int, float)):
        return float(x)
    s = str(x).strip().replace(",", "")
    try:
        return float(s)
    except ValueError:
        return None


# locate the sheet holding the new Profit Margin column
target = None
for s in wb_root.find(q(ns, "sheets")):
    tgt = rid2target.get(s.get(q(REL, "id")))
    if not tgt:
        continue
    cand = tgt.lstrip("/") if tgt.startswith("/") else os.path.normpath(os.path.join("xl", tgt))
    if cand not in blobs:
        continue
    sh_root = ET.fromstring(blobs[cand])
    sh_ns = get_ns(sh_root)
    sheetData = sh_root.find(q(sh_ns, "sheetData"))
    rows = sheetData.findall(q(sh_ns, "row")) if sheetData is not None else []
    hr = next((r for r in rows if r.get("r") == "1"), None)
    if hr is None:
        continue
    hdrs = {}
    for c in hr.findall(q(sh_ns, "c")):
        L = col_letter(c.get("r"))
        if L:
            hdrs.setdefault(L, (raw_value(c, sh_ns) or "").strip().lower())
    if hdrs.get("h") == "profit margin (%)":
        target = (cand, sh_root, sh_ns, rows)
        break
if not target:
    raise SystemExit("ERROR: sheet with 'Profit Margin (%)' column not found")

cand, sh_root, sh_ns, rows = target
rowmap = {int(r.get("r") or 0): r for r in rows}
cells = {}
for rn, row_el in rowmap.items():
    for c in row_el.findall(q(sh_ns, "c")):
        cells[(rn, col_letter(c.get("r")))] = c

filled = 0
for rn in range(2, max(rowmap) + 1):
    c = cells.get((rn, "H"))
    if c is None or c.find(q(sh_ns, "f")) is None:
        continue
    rev = to_num(raw_value(cells.get((rn, "E")), sh_ns))
    prof = to_num(raw_value(cells.get((rn, "G")), sh_ns))
    v = ET.Element(q(sh_ns, "v"))
    if rev is not None and prof is not None and rev != 0:
        v.text = repr(prof / rev)
        c.attrib.pop("t", None)
    else:
        v.text = ""
        c.set("t", "str")
    idx = list(c).index(c.find(q(sh_ns, "f"))) + 1
    c.insert(idx, v)
    filled += 1

sheet_bytes = ET.tostring(sh_root, encoding="UTF-8", xml_declaration=True)
zout = zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED)
for name, info in entries.items():
    zout.writestr(info, sheet_bytes if name == cand else blobs[name])
zout.close()
print("Cached values written for %d margin cells in %s" % (filled, cand))

# --- final error scan across all sheets (cached values) ---
ERRORS = ("#VALUE!", "#DIV/0!", "#REF!", "#NAME?", "#NULL!", "#NUM!", "#N/A")
total_errors = 0
total_formulas = 0
error_summary = {e: [] for e in ERRORS}
for s in wb_root.find(q(ns, "sheets")):
    tgt = rid2target.get(s.get(q(REL, "id")))
    if not tgt:
        continue
    part = tgt.lstrip("/") if tgt.startswith("/") else os.path.normpath(os.path.join("xl", tgt))
    if part not in blobs:
        continue
    root = ET.fromstring(blobs[part])
    sns = get_ns(root)
    sheetData = root.find(q(sns, "sheetData"))
    if sheetData is None:
        continue
    for row in sheetData.findall(q(sns, "row")):
        for c in row.findall(q(sns, "c")):
            if c.find(q(sns, "f")) is not None:
                total_formulas += 1
            texts = []
            v = c.find(q(sns, "v"))
            if v is not None and v.text:
                texts.append(v.text)
