def col_index(letter):
    n = 0
    for ch in letter:
        n = n * 26 + ord(ch) - 64
    return n


def num_to_letter(idx):
    s = ""
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s


def find_col(headers, keywords, exclude=()):
    return [(i, h) for i, h in headers.items()
            if all(k in h for k in keywords) and not any(e in h for e in exclude)]


zin = zipfile.ZipFile(path)
