    sheetData = sh_root.find(q(sh_ns, "sheetData"))
    rows = sheetData.findall(q(sh_ns, "row")) if sheetData is not None else []
    hr = next((r for r in rows if r.get("r") == "1"), rows[0] if rows else None)
    if hr is None:
